(--mono)}.file-labels{grid-column:2;grid-row:2;display:grid;grid-template-columns:repeat(8,1fr);align-items:center;text-align:center;color:#8b988f;font:10px var(--mono)}.square{position:relative;display:grid;place-items:center;min-width:0;min-height:0;border:0;padding:0;cursor:pointer;transition:filter .12s,transform .12s}.square.light{background:var(--lightcell)}.square.dark{background:var(--darkcell)}.square:hover{filter:brightness(1.11);z-index:2}.square.selected{box-shadow:inset 0 0 0 3px var(--green);z-index:3}.square.last-move:after{content:"";position:absolute;inset:0;background:#c8f16935;pointer-events:none}.piece{font-family:'DejaVu Sans',serif;font-size:clamp(22px,3.8vw,42px);line-height:1;position:relative;z-index:1;transition:transform .15s;filter:drop-shadow(0 2px 1px #10151080)}.square:hover .piece{transform:translateY(-2px)}.piece.white{color:#fffdf1;text-shadow:0 1px 0 #727d70,0 2px 0 #546054,0 3px 4px #17201975}.piece.black{color:#18221c;text-shadow:0 1px 0 #bec8b9,0 2px 2px #0e1511}.square.legal-dot:before{content:"";position:absolute;width:24%;height:24%;border-radius:50%;background:#21301c7a;z-index:2;pointer-events:none}.square.legal-capture:before{content:"";position:absolute;inset:4px;border:4px solid #b4e45a9c;border-radius:50%;z-index:2;pointer-events:none}.square.move-source{box-shadow:inset 0 0 0 3px #d8f391}.square.coord-show:after{content:attr(data-coord);position:absolute;bottom:2px;left:3px;color:#18221c99;font:8px var(--mono);z-index:4}.square.dark.coord-show:after{color:#ecf0df88}.board-footer{height:37px;border-top:1px solid #29342d;display:flex;align-items:center;justify-content:space-between}.key-help{font-size:9px;color:#78867c;display:flex;align-items:center;gap:5px}kbd{font:9px var(--mono);border:1px solid #3d4941;border-radius:2px;padding:2px 4px;color:#aab4ab;background:#202923}.help-divider{padding:0 3px;color:#4e5a51}.board-foot-right{font-size:9px;letter-spacing:.8px;color:#b8c2b9;display:flex;align-items:center;gap:8px}.m