ms:center;justify-content:center;gap:13px;color:#7e8b81;font-size:11px;line-height:1.65}.empty-moves>span{font:10px var(--mono);color:#657269;padding:7px;border:1px solid #303a33}.empty-moves b{color:#b4beb5;font-weight:500}.move-pair{display:grid;grid-template-columns:31px 1fr 1fr;align-items:center;min-height:32px;border-bottom:1px solid #222b25;font:10px var(--mono);color:#b8c2b9}.move-number{color:#627066}.move-entry{padding:7px 4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.move-entry.latest{color:var(--green)}.sidebar-bottom{display:grid;grid-template-columns:1fr 1.15fr;gap:8px;margin-top:18px}.undo-button,.new-game-button{height:39px;border-radius:3px;font-size:9px;letter-spacing:.7px;cursor:pointer;transition:.17s}.undo-button{border:1px solid #39443c;background:transparent;color:#9ba69d}.undo-button span{font-size:15px;vertical-align:-1px;margin-right:5px}.undo-button:hover:not(:disabled){border-color:#758472;color:var(--text)}.undo-button:disabled{opacity:.42;cursor:not-allowed}.new-game-button{border:1px solid var(--green);background:var(--green);color:#172015;font-weight:500}.new-game-button:hover{background:#d7ff83;box-shadow:0 0 17px #c8f16930}.new-game-button span{font-size:14px;vertical-align:-1px;margin-right:4px}.side-note{margin-top:18px;color:#637067;font-size:10px;display:flex;align-items:center;gap:8px}.note-mark{color:#91ae60;font-size:14px}.footer{height:43px;border-top:1px solid rgba(255,255,255,.09);display:flex;justify-content:space-between;align-items:center;color:#637067;font-size:8px;letter-spacing:1px}.footer-dot{color:#839764;font-size:6px;padding:0 4px}.modal-backdrop{position:fixed;inset:0;background:#090e0bcf;backdrop-filter:blur(7px);display:grid;place-items:center;padding:20px;z-index:30}.modal-backdrop[hidden]{display:none}.modal{position:relative;width:min(570px,100%);background:#1b231e;border:1px solid #3b493d;border-radius:5px;padding:34px 38px 26px;box-shadow:0 30px 90px #0009}.modal-close{position:absolute;right:17px;top:14px;color:#9da99f;border:0;background:none;font-size:25px;cursor:pointer}.modal h2{font:600 31px/1.1 var(--display);letter-spacing:-1.3px;margin:10px 0}.modal h2 span{color:var(--green)}.modal-intro{font-size:12px;line-height:1.65;color:#9eaaa0;max-width:455px;margin-bottom:22px}.rule-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px 22px}.rule-grid article{display:flex;gap:11px}.rule-glyph{font:25px 'DejaVu Sans',serif;color:var(--green);width:26px;flex:none}.rule-grid b{font:600 12px var(--display);color:#e6ece4}.rule-grid p{font-size:10px;line-height:1.6;color:#929f95;margin:4px 0 0}.modal-foot{border-top:1px solid #303a33;padding-top:14px;margin-top:22px;color:#78857b;font-size:9px}.toast{position:fixed;left:50%;bottom:26px;transform:translate(-50%,12px);padding:11px 17px;background:#d1f47b;color:#1b2516;font:11px var(--mono);border-radius:3px;box-shadow:0 5px 25px #0007;opacity:0;pointer-events:none;transition:.2s;z-index:40}.toast.show{opacity:1;transform:translate(-50%,0)}
