@media(max-width:780px){.app-shell{padding:0 18px}.layout{grid-template-columns:1fr;gap:25px;padding-top:25px}.sidebar{display:grid;grid-template-columns:1fr 1fr;column-gap:22px;align-items:start}.turn-card{grid-column:1/-1}.captured-section,.moves-section{margin-top:21px}.moves-section{grid-row:2/4}.sidebar-bottom{grid-column:1/-1;margin-top:20px}.side-note{grid-column:1/-1}.board-frame{max-width:620px}.footer{margin-top:5px}.match-heading h1{font-size:39px}}
